    try:
        data = line.encode("utf-8")
    except UnicodeEncodeError:
        raise ParseError(1, "entry is not valid UTF-8 text") from None
    try:
        with open(args.file, "a+b") as fh:
            fh.seek(0, io.SEEK_END)
            if fh.tell() > 0:
                fh.seek(-1, io.SEEK_END)
                needs_newline = fh.read(1) != b"\n"
                fh.seek(0, io.SEEK_END)
            else:
                needs_newline = False
            fh.write((b"\n" if needs_newline else b"") + data + b"\n")
    except OSError as exc:
        raise _Unreadable("cannot write %s: %s" % (args.file, exc)) from None
    return line


_COMMANDS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "add": _cmd_add,
    "export": _cmd_export,
}


